INSERT INTO public.drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('a015a46c-1380-4433-b149-87da1434a839', 0, 2200, 'Setup — attacker (blue) on ball at halfway, defender (red) 15m away guarding mini-goal. Two cones mark a 20x15m channel.', '[{"id":"p1","type":"player","x":50,"y":75,"color":"#0ea5e9","label":"A"},{"id":"b1","type":"ball","x":50,"y":76,"color":"#f5f5f5"},{"id":"p2","type":"player","x":50,"y":35,"color":"#ef4444","label":"D"},{"id":"c1","type":"cone","x":30,"y":20,"color":"#f97316"},{"id":"c2","type":"cone","x":70,"y":20,"color":"#f97316"},{"id":"c3","type":"cone","x":30,"y":85,"color":"#f97316"},{"id":"c4","type":"cone","x":70,"y":85,"color":"#f97316"},{"id":"g1","type":"mini-goal","x":50,"y":10}]', '[]'),
